  "`{0}` гэсэн эх сурвалж байхгүй эсвэл танд үзэх эрх алга.": "There is no source `{0}`, or you do not have permission to view it.",
  "`actual` нь АЖЛЫН ХУУДСААС тооцоолсон бодит гүйцэтгэл — дашбоардын толгойн тоо энэ. ": "`actual` is the real progress computed FROM THE WORK SHEET — this is the headline figure on the dashboard. ",
  "`Bagts_<SFX>` (багц), `MNG_ajiltani_too_<SFX>` (монгол), `G_ajiltanii_too_<SFX>` (гадаад), ": "`Bagts_<SFX>` (package), `MNG_ajiltani_too_<SFX>` (domestic), `G_ajiltanii_too_<SFX>` (foreign), ",
  "`building_progress` — «Барилгын хяналт» дашбоардын БОДИТ гүйцэтгэл: нийт хувь, багц бүрийн ": "`building_progress` — the ACTUAL progress from the “Construction monitoring” dashboard: overall percentage, per-package ",
  "`mon:building` давхаргад хандах эрх алга.": "No permission to access the `mon:building` layer.",
  "`negj_une` (нэгж үнэ) нь давхаргын геометрээс хамаарч ӨӨР утгатай: цэг → ширхэг, шугам → 100 м, талбай → м². Нэгжийг талбарын нэрээр ТААМАГЛАЖ болохгүй.": "`negj_une` (unit price) means DIFFERENT things depending on the layer geometry: point → per item, line → per 100 m, polygon → per m². Do NOT infer the unit from the field name.",
  "`Niit_ajiltan_<SFX>` (нийт ажилтан), `Tehnik_<SFX>` (техник) — ": "`Niit_ajiltan_<SFX>` (total workers), `Tehnik_<SFX>` (equipment) — ",
  "`note`-д юу бичих вэ (1–2 өгүүлбэр):": "What to write in `note` (1–2 sentences):",
  "`Population` (орон сууцны оршин суугч) ба `Huchin_chadal` (facility-ийн багтаамж) нь ӨӨР төрлийн үзүүлэлт — шууд нийлүүлж болохгүй. ": "`Population` (residents in housing) and `Huchin_chadal` (facility capacity) are DIFFERENT kinds of indicator — they must not simply be added. ",
  "`Total_population` бол тэдгээрийн механик нийлбэр тул ТООЦООНД АШИГЛАХГҮЙ. ": "`Total_population` is a mechanical sum of the two, so DO NOT USE IT in calculations. ",
  "`whole: true` тэмдэгтэй эх сурвалж нь БҮХЭЛДЭЭ энэ багцынх — мөрөөр шүүгээгүй, ": "A source marked `whole: true` belongs ENTIRELY to this package — it was not filtered by row, ",
