  "Ажилбар": "Activities",
  "Хоцролт": "Delay",
  "Оруулсан ажлын жигнэсэн гүйцэтгэл. Бүлгийн мөр = Σ(Нийт_жин×Гүйцэтгэл) / Σ(Нийт_жин). Бэлтгэл ажлыг нийт дүнд оруулаагүй. Төлөвлөсөн ирээдүйн мөрүүд устгагдсан тул оруулсан ажлын хэмжээгээр тооцно.": "Weighted progress of the entered work. Group row = Σ(total weight × progress) / Σ(total weight). Preparation work is excluded from the grand total. Planned future rows were removed, so completion is measured over the entered scope.",
