  "Үйлчилгээ JSON биш хариу буцаав — сүлжээгээ шалгана уу": "The service returned a non-JSON response — check your network",
  "{0}: {1} мөр ирлээ, {2} байх ёстой. Нэмэгдсэн мөрүүдийг суурь агшинтай тулгаж чадсангүй — эх хүснэгтийн бүтэц өөрчлөгдсөн бол шатлалын зураглалыг (bagts.trees.ts) дахин гаргах шаардлагатай.": "{0}: got {1} rows, expected {2}. The added rows could not be aligned against the base snapshot — if the source table structure changed, the hierarchy map (bagts.trees.ts) must be regenerated.",
  "Мөр нэмэх": "Add row",
  "«Гүйцэтгэл бөглөх» хуудсанд бүлэг дотор шинэ ажлын мөр нэмэх. Хуудасны бүтэц өөрчлөгдөж, жин ба мөнгөн дүн бүхэлдээ дахин бодогдоно.": "Add a new task row inside a group on the “Fill in progress” sheet. The sheet structure changes and all weights and amounts are recomputed.",
  "⚠️ ArcGIS-т бичигдсэнгүй — эрх түр зөвхөн энэ browser-т. Холболтоо шалгаад дахин дарна уу.": "⚠️ Not written to ArcGIS — the permission is temporarily local to this browser. Check your connection and click again.",
  "Энэ багана тухайн үйлчилгээнд байхгүй — хадгалах газаргүй тул засагдахгүй. AGOL дээр талбарыг нэмж өгөх шаардлагатай.": "This column does not exist in that service — there is nowhere to store it, so it cannot be edited. The field must be added in AGOL.",
  "{0} — дарж бичнэ": "{0} — click to type",
  "QAQC — Inspection Test Plan": "QAQC — Inspection Test Plan",
  "«Гүйцэтгэл бөглөх» хуудасны Inspection Test Plan хэсгийг (М-акт, FIC, MA, MIR) бөглөх. Гүйцэтгэлийн хувь бөглөх эрхээс тусдаа.": "Fill in the Inspection Test Plan section (M-act, FIC, MA, MIR) on the “Fill in progress” sheet. Separate from the permission to fill in progress percentages.",
  "Inspection Test Plan (М-акт, FIC, MA, MIR) бөглөхөд «QAQC» эрх шаардлагатай — «Хэрэглэгчдийн эрх удирдах» хэсгээс олгоно.": "Filling in the Inspection Test Plan (M-act, FIC, MA, MIR) requires the “QAQC” permission — grant it under “Manage user permissions”.",
  "Хуудас засагдахгүй горимд байна — өнөөдөр аль хэдийн хяналтад илгээгдсэн (эсвэл зөвхөн харах горим).": "The sheet is read-only — it has already been submitted for review today (or this is view-only mode).",
  "Засах шаардлагатай — буцаагдсан": "Needs fixing — returned",
  "Буцаагдсан ажил алга — бүх илгээлт хэвийн явж байна.": "No returned work — all submissions are moving normally.",
  "Илгээсэн — хянагдаж байна": "Submitted — under review",
  "Батлагдсан — эх хүснэгтэд шилжсэн": "Approved — transferred to the source table",
  "Бөглөх, илгээх, зөвшөөрөл — гүйцэтгэлийн бүх урсгал нэг дор": "Fill in, submit, approve — the whole progress workflow in one place",
  "Танд нэг ч багц хуваарилагдаагүй байна. Админ «Гүйцэтгэлийн урсгал» хэсэгт багц зааж өгсний дараа ажлууд харагдана.": "No packages are assigned to you. Work will appear once an administrator assigns packages under “Progress workflow”.",
  "Танд нэг ч багц хуваарилагдаагүй байна. «Хэрэглэгчдийн эрх удирдах → Гүйцэтгэлийн урсгал» хэсэгт админ таныг шатанд томилж, багц зааж өгсний дараа энэ хуудас нээгдэнэ.": "No packages are assigned to you. This page opens once an administrator assigns you to a stage and grants packages under “Manage user permissions → Progress workflow”.",
