  "Бодит эзлэхүүн": "Actual volume",
  "Төлөвлөгөөт эзлэхүүн": "Planned volume",
  "⚠️ Хүснэгт нь append-only: багц бүрд огноо тутам мөр НЭМЭГДДЭГ. Одоогийн байдлыг гаргахдаа багц бүрийн ХАМГИЙН СҮҮЛИЙН огноотой мөрийг ав — бүх мөрөөр дундаж авбал хуучин заалт хольж хазайна. ": "⚠️ The table is append-only: a row is ADDED per package per date. To report the current state, take each package’s LATEST-dated row — averaging over all rows mixes in stale readings and skews the result. ",
  "⚠️ Хувь нь 0–100 (БУТАРХАЙ 0–1 БИШ) — ×100 хийхгүй. ": "⚠️ Percentages are 0–100 (NOT fractional 0–1) — do not multiply by 100. ",
