  "{0} багц · {1} талбар": "{0} packages · {1} parcels",
  "Хуваарь төлөвлөх": "Plan the schedule",
  "«Хуваарь» харагдацад ажлын эхлэх/дуусах огноог засах. Нэг огноо солиход төлөвлөгөөт хувь, тайлан, хоцрогдлын дохио бүгд дахин бодогдоно — тиймээс бөглөх эрхээс тусдаа.": "Edit task start/finish dates in the Schedule view. Changing one date recomputes planned progress, the report and every delay signal — hence separate from the data-entry right.",
  "Хуваарь": "Schedule",
  "Ажлын эхлэх, дуусах хугацаа — блокийн хэмнэлээр": "Task start and finish dates — by block rhythm",
  "Танд хуваарь засах эрх алга — зөвхөн харна. Эрхийг админ «Хуваарь төлөвлөх» гэж тусад нь олгоно.": "You do not have edit rights — view only. An admin grants “Plan the schedule” separately.",
