  "Гэрээний код (G01…G76) — актын хүснэгттэй нэгдэх ТҮЛХҮҮР ({0}.{1} → энэ талбар)": "Contract code (G01…G76) — the KEY that joins to the certificate table ({0}.{1} → this field)",
  "⚠️ МӨРИЙН ТӨРӨЛ: «{0}» = гэрээний мастер мөр (76) · «{1}» = сарын хэмжилт (131) · «{2}» = өмнөх онд шилжүүлсэн (2). Аливаа нийлбэр/тооллын өмнө ЗААВАЛ энэ талбараар шүү.": "⚠️ ROW TYPE: «{0}» = contract master row (76) · «{1}» = monthly measurement (131) · «{2}» = transferred in a prior year (2). ALWAYS filter on this field before any sum or count.",
  "Жил — зөвхөн үеийн мөрөнд (ГЭРЭЭ мөрөнд хоосон)": "Year — period rows only (empty on the contract master row)",
  "Сар 1–12, тэглэлгүй — зөвхөн «{0}» мөрөнд": "Month 1–12, unpadded — «{0}» rows only",
  "Төслийн ангилал (6 утга: ОРОН СУУЦНЫ ХОРООЛЛЫН БАРИЛГАЖИЛТ, ИНЖЕНЕРИЙН ДЭД БҮТЭЦ, НИЙГМИЙН ДЭД БҮТЭЦ, «ГАДНА ТОХИЖИЛТ, ӨНДӨРЖИЛТ», ТЭЗҮ ЗУРАГ ТӨСӨЛ, БУСАД). 4 гэрээнд ХООСОН — «0» гэж бичигдээгүй, NULL.": "Project category (6 values: housing-district construction, engineering infrastructure, social infrastructure, external landscaping and grading, feasibility study and design, other). EMPTY on 4 contracts — NULL, not the string «0».",
  "Багц — ҮНДСЭН («БАГЦ-16»). Бүлэглэхэд ХЭРЭГЛЭХГҮЙ: БАГЦ-16.1…16.7-г нэг мөр болгож нурааж хаяна.": "Package — TOP level («БАГЦ-16»). DO NOT group by this: it collapses БАГЦ-16.1…16.7 into a single row.",
  "Дэд багц («БАГЦ-16.3») — багцаар ШҮҮХ/БҮЛЭГЛЭХДЭЭ ЭНИЙГ ашигла. Дэд хуваарьгүй бол үндсэн багцтайгаа тэнцүү. «БАГЦ 1-4», «БАГЦ 1-6 БАГЦ 8-17», «БҮХ БАГЦ» гэсэн МУЖИЙН утга ба NULL ч байна — нэг багцад оноож болохгүй.": "Sub-package («БАГЦ-16.3») — use THIS to filter or group by package. Equals the top package when there is no subdivision. RANGE values («БАГЦ 1-4», «БАГЦ 1-6 БАГЦ 8-17», «БҮХ БАГЦ») and NULLs also occur — they must not be assigned to a single package.",
  "Гүйцэтгэгч байгууллага — актын хүснэгтийн {0}-тай ҮСЭГ БҮРЭЭР тэнцүү": "Contractor organisation — byte-for-byte equal to {0} in the certificate table",
  "Тухайн үеийн ТӨЛӨВЛӨСӨН мөнгөн дүн, ₮. Хоосон = мэдээлэлгүй, 0 = тэг гүйцэтгэл — хоёрыг НЭГТГЭХГҮЙ.": "PLANNED amount for the period, ₮. Empty = no data, 0 = zero performance — never conflate the two.",
