  "⚠️ МӨРИЙН ТӨРЛӨӨР ШҮҮХГҮЙ БОЛ БУРУУ: хүснэгт 209 мөртэй ч гэрээ ердөө 76. Гэрээний тоо/төсөв/захирамж асуувал `{0}`, сарын урсгал асуувал `{1}`, хэмжилттэй бүх мөр бол `{2}`. Мөнгөний нийлбэр шүүлтгүй ч зөв гарч мэднэ (мастер багана үеийн мөрөнд хоосон) — алдаа зөвхөн ТООЛОЛТ ба ДУНДАЖ дээр гарна. ": "⚠️ WRONG WITHOUT A ROW-TYPE FILTER: the table has 209 rows but only 76 contracts. Use `{0}` for contract counts, budgets and ordinances, `{1}` for the monthly flow, `{2}` for every measured row. Money sums may look right even unfiltered (master columns are empty on period rows) — the error shows up only in COUNTS and AVERAGES. ",
  "⚠️ Багцаар шүүх/бүлэглэхдээ ЗААВАЛ `{0}` (дэд багц — ЖИМС) ашигла; `{1}` нь БАГЦ-16.1…16.7-г нэг болгож нурааж хаяна. ": "⚠️ ALWAYS use `{0}` (sub-package — the LEAF) to filter or group by package; `{1}` collapses БАГЦ-16.1…16.7 into one. ",
  "⚠️ Актын хүснэгттэй (`ds:ipc`) БАГЦЫН НЭРЭЭР БИШ, гэрээний кодоор нэгд: `{0}` → `{1}`. ": "⚠️ Join the certificate table (`ds:ipc`) by contract code, NOT by package name: `{0}` → `{1}`. ",
  "⚠️ ХУВЬ, ӨССӨН (хуримтлагдсан) дүн, суутгалын томьёо, төлөх дүн, зөрүү, «ЖИЛИЙН НИЙТ» мөр — эдгээр багана ХАСАГДСАН, хүснэгтэд БАЙХГҮЙ. Хэрэгтэй бол мөрүүдээ татаад ӨӨРӨӨ бод; байхгүй багана нэрлэвэл хүсэлт унана. ": "⚠️ Percentages, cumulative amounts, deduction formulas, payable amounts, variances and «annual total» rows were REMOVED — those columns do not exist. Fetch the rows and compute them yourself; naming a missing column makes the query fail. ",
  "⚠️ «Өмнө шилжүүлсэн» дүн ГЭРЭЭ ТУС БҮРЭЭР БАЙХГҮЙ — зөвхөн «{0}» төрлийн 2 мөрийн нийлбэр (4,058,800,000 ₮) хэлбэрээр л бий. ": "⚠️ «Previously transferred» does NOT exist per contract — only as the sum of the 2 «{0}» rows (4,058,800,000 ₮). ",
  "⚠️ Хуваарьт ЦООРХОЙ бий: 2026-01-д ямар ч мөр байхгүй. Сарын тэнхлэгийг өгөгдөлд байгаа саруудаас угсарвал график нэг сар шилжинэ — {0}…{1} хүртэлх ТАСРАЛТГҮЙ мужаар яв, байхгүй сарыг 0 гэж нөх. ": "⚠️ The schedule has a GAP: there is no row at all for 2026-01. Building the month axis from the months present shifts the chart by one slot — walk the CONTINUOUS range {0}…{1} and back-fill absent months with 0. ",
  "⚠️ Огноонууд `DateOnly` — «2024-04-08» гэсэн МӨР болж ирнэ, epoch мс БИШ. ": "⚠️ Dates are `DateOnly` — they arrive as STRINGS like «2024-04-08», not epoch ms. ",
