  "⚠️ ХУУЧИН ШҮҮЛТИЙГ ХЭРЭГЛЭХГҮЙ: 59 мөр БҮГД жинхэнэ акт. «IPC-n/APC-n хэлбэртэй эсэх» шалгалт, «багц ≠ 0» хамгаалалт хоёулаа ХЭРЭГГҮЙ — {0} нь одоо актын КОД (багц БИШ) тул тэдгээр шүүлт бүх мөрийг хаяна. ": "⚠️ DO NOT APPLY THE OLD FILTERS: all 59 rows are real certificates. Both the «looks like IPC-n/APC-n» test and the «package ≠ 0» guard are UNNECESSARY — {0} is now the certificate CODE (not a package), so those filters would discard every row. ",
  "⚠️ Гэрээний/төсөвт үнэ ЭНД БАЙХГҮЙ — тэр нь зөвхөн `ds:cashflow2` ({0} төсөвт өртөг, {1} гэрээний эрхийн дүн). Хуучин хүснэгтэд актын дүнтэй нэг баганад холилдож нийлбэрийг 5.4 дахин хөөрөгддөг байсан. ": "⚠️ Contract and budget prices are NOT here — they live only in `ds:cashflow2` ({0} budget cost, {1} contract authority amount). In the old table they shared a column with certificate amounts and inflated the sum 5.4×. ",
  "⚠️ Гэрээтэй нэгдэхдээ багцын нэр тааруулахгүй, ЖИНХЭНЭ түлхүүрээр: `{0}` → `ds:cashflow2`.`{1}` (мастер мөр). ": "⚠️ Join to contracts by the REAL key, not by matching package names: `{0}` → `ds:cashflow2`.`{1}` (master row). ",
  "⚠️ БОДОГДОХ БАГАНА БАЙХГҮЙ (олгох дүн, үлдэгдэл, хувь, хоногийн тоо бүгд хасагдсан) — өөрөө бод: ОЛГОХ = {0} − ({1}); ТӨЛСӨН = {2}-ийн нийлбэр; ҮЛДЭГДЭЛ = олгох − төлсөн. ": "⚠️ THERE ARE NO DERIVED COLUMNS (payable, outstanding, percentages and day counts were all removed) — compute them: PAYABLE = {0} − ({1}); PAID = sum of {2}; OUTSTANDING = payable − paid. ",
  "⚠️ Гэхдээ {0} ба {1} нь ТЕКСТ талбар (бүхэлдээ хоосон) — тэдгээрийг `outStatistics`-д оруулбал ArcGIS 400 буцаана. Гүйлгээний нийлбэрийг зөвхөн {2}-ээр асуу, эсвэл мөрүүдийг татаад тоол. ": "⚠️ But {0} and {1} are TEXT fields (entirely empty) — putting them in `outStatistics` makes ArcGIS return 400. Ask for the transaction sum via {2} only, or fetch the rows and add them up. ",
  "⚠️ 59 актын 32-т ашиглах огноо АЛГА (null ≠ 0). Сарын цуваанд эдгээрийг ОРУУЛАХГҮЙ — сүүлийн сар руу шахвал хуурамч оргил үүснэ; харин багц/нийт дүнд ҮЛДЭНЭ. Тиймээс «сараар нийлбэр» ба «нийт» хоёр ЗӨРНӨ, зөрүүг хариултад дурд. ": "⚠️ 32 of the 59 certificates have NO usable date (null ≠ 0). Keep them OUT of the monthly series — clamping them onto the last month fabricates a spike; they DO stay in package and grand totals. So «sum by month» and «total» will DIFFER — mention the gap in your answer. ",
  "⚠️ Огноо `DateOnly` — «2026-06-08» гэсэн МӨР, epoch мс БИШ. Сарыг эхний 7 тэмдэгтээс ав. ": "⚠️ Dates are `DateOnly` — STRINGS like «2026-06-08», not epoch ms. Take the month from the first 7 characters. ",
