  "Хуваарийн хамралт нь багц тус бүрийн бүх мөрийг татаж байж бодогддог. Схем нээх бүрд тэр хүсэлтийг явуулбал бусад тоо ч удаашрах тул энд ЗОРИУДААР тооцохгүй — «Хуваарь» харагдацаас үзнэ үү.": "Schedule coverage is computed by pulling every row of every package. Issuing those requests each time the diagram opens would slow the other figures down too, so it is DELIBERATELY not computed here — see the “Schedule” view.",
